args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?grandfather ?grandfatherLabel WHERE {
  dbr:George_Tupou_V (dbp:father|dbo:parent) ?father .
  ?father (dbp:father|dbo:parent) ?grandfather .
  OPTIONAL { ?grandfather rdfs:label ?grandfatherLabel . FILTER(lang(?grandfatherLabel) = "en") }
}

